const data = item.json.body?.result?.data ?? {};
const tags = Array.isArray(data.tags) ? data.tags : [];
const suggestedTags = Array.isArray(data.suggestedTags) ? data.suggestedTags : [];

const status = data.bridgeVideoEvaluation.light;
const number = item.json.body?.number ?? "";
const score = $json.body.result.data.bridgeVideoEvaluation.finalScore;
const reason = $json.body.result.data.bridgeVideoEvaluation.reason;

let light = "";

if (status === "green") {
  light = "🟢";
} else if (status === "yellow") {
  light = "🟡";
} else if (status === "red") {
  light = "🔴";
}

const blocks = Array.isArray(data.questionScoringBlocks) ? data.questionScoringBlocks : [];
const redFlags = blocks.flatMap((b) => Array.isArray(b.redFlags) ? b.redFlags : []);
return {
  json: {
    number,
    score,
    reason,
    tags: tags.join(", "),
    suggestedTags: suggestedTags.join(", "),
    redFlags: redFlags.join(", "),
    light
  }
};

return {
  json: {
    ...$json,
    redFlags: Array.isArray($json.redFlags) ? $json.redFlags.join(', ') : '',
    missingMustInclude: Array.isArray($json.missingMustInclude) ? $json.missingMustInclude.join(', ') : '',
  }
};

const rows = $input.all().map(i => i.json);
// Normaliza y deduplica por par objection+proofNeeded
const seen = new Set();
const tagCatalog = [];
for (const r of rows) {
  const objection = (r["Objection"] ?? "").toString().trim();
  const proofNeeded = (r["Proof needed"] ?? "").toString().trim();
  // Si no hay objection, no sirve para clasificar
  if (!objection) continue;
  const key = `${objection.toLowerCase()}|${proofNeeded.toLowerCase()}`;
  if (seen.has(key)) continue;
  seen.add(key);
  tagCatalog.push({
    objection,
    proofNeeded, // puede quedar ""
  });
}
return [
  {
    json: {
      tagCatalog
    }
  }
];

return items.map(item => {
  const filename = item.json.name;

  const nameWithoutExtension = filename.replace(/\.[^/.]+$/, "");

  const parts = nameWithoutExtension.split("-");

  const lastPart = parts[parts.length - 1];
  const hasOK = lastPart.toUpperCase() === "OK";

  const nameParts = parts.slice(2, -1);

  const interviewerName = nameParts
    .map(part => part.charAt(0) + part.slice(1).toLowerCase())
    .join(" ");

  item.json.interviewerName = interviewerName;
  item.json.hasOk = hasOK ? "SI" : "NO"

  return item;
});

const result = [];

for (const item of items) {
  const data = item.json;

  const videosField = data["Upload your video\n*up to 5 videos"];

  if (!videosField) continue;

  // Formateo de fecha
  const rawTimestamp = data["Timestamp"];

  // "5/1/2026 13:38:22"
  const [datePart, timePart] = rawTimestamp.split(" ");
  const [month, day, year] = datePart.split("/");

  const formattedDate =
    `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;

  const [hours, minutes] = timePart.split(":");
  const formattedTime = `${hours}:${minutes}`;

  // Autorización
  const authorization =
    data["⭐️ By sharing your video with us, you’re allowing us to share it within our community!"]
    === "If you’re happy for us to feature your video on our social media as well, feel free to reply with “OK” — we’d love to highlight your story :yellow_heart:"
      ? "SI"
      : "NO";

  // split videos
  const videoUrls = videosField
    .split(",")
    .map(url => url.trim())
    .filter(url => url.length > 0);

  for (const videoUrl of videoUrls) {
    result.push({
      json: {
        name: data["What's your name?"],
        email: data["Email Address"],
        formatted_date: formattedDate,
        formatted_time: formattedTime,
        authorization,
        video_url: videoUrl,
      }
    });
  }
}

return result;

